selected.compute:
options = read('/input/options')
existing = read('/output/selection')
if existing:
    result = existing
else:
    result = []
    for k in range(goal['min_count'], goal['max_count'] + 1):
        for group in combinations(options, k):
            ids = [record['id'] for record in group]
            if valid(ids):
                result = sorted(ids, key=lambda option_id: (next(record['rank'] for record in options if record['id'] == option_id), option_id))
                break
        if result:
            break

selected.effects:
if not exists('/output/selection'):
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', read('/output/selection'))
if exists('/tmp/cache'):
    delete('/tmp/cache')
